export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parseDate = (s) => {
    s = str(s).trim();
    if (!s) return NaN;
    return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  };
  const fresh24h = (updatedAt) => {
    const ms = parseDate(updatedAt);
    return isFinite(ms) && (Date.now() - ms) <= 24 * 3600 * 1000;
  };
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (k) => String(texts[k] || k);
  const nowIso = new Date().toISOString();
  const deny = (errText) => ({ verdict: 'deny', errText: errText, bid: '', text: '', replyMarkup: null, body: '', eventId: '', mediaChatId: '', mediaMessageId: '', nowIso: nowIso });
  const srows = arr(inputs.sessionRecords).map(flat)
    .filter((r) => str(r.telegram_id) === str(inputs.telegramId));
  const s = srows[0];
  if (!s || str(s.scenario) !== 'broadcast' || str(s.step) !== 'await_event' || !fresh24h(s.updated_at))
    return deny(t('common.err.session_expired'));
  let body = '', createdBy = '', mediaChatId = '', mediaMessageId = '';
  try {
    const d = JSON.parse(str(s.draft) || '{}');
    body = str(d.body);
    createdBy = str(d.createdBy);
    mediaChatId = str(d.mediaChatId);
    mediaMessageId = str(d.mediaMessageId);
  } catch (e) { body = ''; }
  // W79 (#131): фото без подписи допустимо — тело пустое, но есть источник
  // copyMessage; пустыми оба не могут быть.
  if ((body === '' && mediaMessageId === '') || (createdBy !== '' && createdBy !== str(inputs.telegramId)))
    return deny(t('common.err.session_expired'));
  const erows = arr(inputs.eventRecords).map(flat).filter((e) => str(e.id) === str(inputs.eventId));
  const ev = erows[0];
  if (!ev) return deny(t('common.err.event_not_found'));
  if (str(ev.status) !== 'published' && str(ev.status) !== 'finished')
    return deny(t('common.err.event_not_found'));
  const staffRows = arr(inputs.staffRecords).map(flat).filter((r) => str(r.telegram_id) === str(inputs.telegramId));
  const chapterId = str(ev.chapter_id || '');
  const srow = staffRows[0];
  const sc = srow ? str(srow.chapter_id || '') : '';
  if (!srow || (sc !== '' && chapterId !== '' && sc !== chapterId)) return deny(t('common.err.forbidden'));
  const bid = 'b' + Date.now().toString(36) + Math.floor(Math.random() * 1296).toString(36);
  const segBtn = (seg, label) => [{ text: label, callback_data: 'bcast:seg:' + bid + ':' + seg }];
  const kb = [
    segBtn('registered', t('bcast.btn.seg_registered')),
    segBtn('attended', t('bcast.btn.seg_attended')),
    segBtn('no_show', t('bcast.btn.seg_noshow')),
    segBtn('all_consent', t('bcast.btn.seg_all')),
    [{ text: t('bcast.btn.cancel'), callback_data: 'bcast:cancel:' + bid }],
  ];
  const text = t('bcast.ask.segment')
    + '\n— ' + t('bcast.segment.registered')
    + '\n— ' + t('bcast.segment.checked_in')
    + '\n— ' + t('bcast.segment.no_show')
    + '\n— ' + t('bcast.segment.all_consent');
  return { verdict: 'ok', errText: '', bid: bid, text: text, replyMarkup: { inline_keyboard: kb }, body: body, eventId: str(ev.id), mediaChatId: mediaChatId, mediaMessageId: mediaMessageId, nowIso: nowIso };
};

export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const arr = (src) => Array.isArray(src) ? src : (src && Array.isArray(src.records) ? src.records : []);
  const flat = (rec) => {
    const out = {};
    const cells = (rec && rec.cells) || {};
    Object.keys(cells).forEach((fid) => {
      const c = cells[fid];
      if (c && typeof c === 'object' && typeof c.fieldName === 'string') out[c.fieldName] = c.value === undefined || c.value === null ? '' : String(c.value);
    });
    return out;
  };
  const parseDate = (s) => {
    s = str(s).trim();
    if (!s) return NaN;
    return Date.parse(/[Zz]$/.test(s) || /[+-][0-9]{2}:?[0-9]{2}$/.test(s) ? s : s + 'Z');
  };
  const fmtTash = (iso) => {
    const ms = parseDate(iso);
    if (!isFinite(ms)) return '';
    return new Intl.DateTimeFormat('ru-RU', { day: 'numeric', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Tashkent' }).format(new Date(ms));
  };
  const texts = (inputs.texts && typeof inputs.texts === 'object') ? inputs.texts : {};
  const t = (k, vars) => {
    let s = String(texts[k] || k);
    if (vars) Object.keys(vars).forEach((key) => { s = s.split('{' + key + '}').join(String(vars[key])); });
    return s;
  };
  const deny = (errText) => ({ verdict: 'deny', errText: errText, count: 0, text: '', replyMarkup: null });
  const seg = str(inputs.segment);
  if (['all_consent', 'registered', 'attended', 'no_show'].indexOf(seg) < 0)
    return deny(t('common.err.generic'));
  const brows = arr(inputs.broadcastRecords).map(flat);
  const b = brows[0];
  if (!b || str(b.id) === '') return deny(t('common.err.generic'));
  if (str(b.created_by) !== str(inputs.telegramId)) return deny(t('common.err.forbidden'));
  if (str(b.status) !== 'draft') return deny(t('common.err.generic'));
  const evrows = arr(inputs.eventRecords).map(flat).filter((e) => str(e.id) === str(b.event_id));
  const ev = evrows[0];
  if (!ev) return deny(t('common.err.event_not_found'));
  const staffRows = arr(inputs.staffRecords).map(flat).filter((r) => str(r.telegram_id) === str(inputs.telegramId));
  const chapterId = str(ev.chapter_id || '');
  const srow = staffRows[0];
  const sc = srow ? str(srow.chapter_id || '') : '';
  if (!srow || (sc !== '' && chapterId !== '' && sc !== chapterId)) return deny(t('common.err.forbidden'));
  const blocked = {};
  arr(inputs.usersByIdsRecords).map(flat).forEach((u) => {
    if (str(u.blocked_bot) === 'true') blocked[str(u.telegram_id)] = true;
  });
  arr(inputs.consentRecords).map(flat).forEach((u) => {
    if (str(u.blocked_bot) === 'true') blocked[str(u.telegram_id)] = true;
  });
  let members = [];
  if (seg === 'all_consent') {
    members = arr(inputs.consentRecords).map(flat)
      .filter((u) => str(u.consent_marketing) === 'true' && str(u.telegram_id) !== '' && !blocked[str(u.telegram_id)])
      .map((u) => str(u.telegram_id));
  } else {
    const regs = arr(inputs.regRecords).map(flat)
      .filter((r) => str(r.event_id) === str(b.event_id) && str(r.status) === 'registered');
    const attendedIds = {};
    regs.forEach((r) => { if (str(r.checked_in_at) !== '') attendedIds[str(r.telegram_id)] = true; });
    if (seg === 'no_show') {
      const endsMs = parseDate(ev.ends_at);
      if (!isFinite(endsMs) || endsMs > Date.now()) {
        const when = fmtTash(ev.ends_at) || str(ev.ends_at);
        return { verdict: 'locked', errText: t('bcast.segment.no_show_locked', { when: when }), count: 0, text: '', replyMarkup: null };
      }
      members = regs.filter((r) => str(r.checked_in_at) === '' && !attendedIds[str(r.telegram_id)]).map((r) => str(r.telegram_id));
    } else if (seg === 'attended') {
      members = Object.keys(attendedIds);
    } else {
      members = regs.map((r) => str(r.telegram_id));
    }
    members = members.filter((id) => id !== '' && !blocked[id]);
  }
  const seen = {};
  members = members.filter((id) => { if (seen[id]) return false; seen[id] = true; return true; });
  const bid = str(b.id);
  const kb = [
    [{ text: t('bcast.btn.test'), callback_data: 'bcast:test:' + bid }],
    [{ text: t('bcast.btn.send'), callback_data: 'bcast:send:' + bid }],
    [{ text: t('bcast.btn.cancel'), callback_data: 'bcast:cancel:' + bid }],
  ];
  const text = t('bcast.preview.title') + '\n' + str(b.body) + '\n' + t('bcast.preview.count', { count: members.length });
  return { verdict: 'ok', errText: '', count: members.length, text: text, replyMarkup: { inline_keyboard: kb } };
};

