export const code = async (inputs) => {
  const err = inputs.sendErr;
  const hasErr = err !== undefined && err !== null && !(typeof err === 'object' && Object.keys(err).length === 0) && err !== '';
  return { delivered: !hasErr, nowIso: new Date().toISOString() };
};

