  if (!ctx.segSet) return deny(t('common.err.generic'));
  if (!ctx.hasTest) return deny(t('bcast.send.blocked_no_test'));
  const ev = arr(inputs.eventRecords).map(flat).filter((e) => str(e.id) === str(ctx.eventId))[0];
