export const code = async (inputs) => {
  const str = (v) => String(v === undefined || v === null ? '' : v);
  const parts = str(inputs.callbackData).split(':');
  const ops = ['ev', 'seg', 'test', 'send', 'cancel'];
  let op = '', bid = '', arg = '', valid = false;
  if (parts[0] === 'bcast' && ops.indexOf(parts[1]) >= 0) {
    op = parts[1];
    if (op === 'ev') { arg = str(parts[2]); valid = arg !== ''; }
    else if (op === 'seg') { bid = str(parts[2]); arg = str(parts[3]); valid = bid !== '' && arg !== ''; }
    else if (op === 'test' || op === 'send') { bid = str(parts[2]); valid = bid !== ''; }
    else if (op === 'cancel') { bid = str(parts[2]); valid = true; }
  }
  return { op: op, bid: bid, arg: arg, valid: valid };
};
